package com.nexamart.backend.domain;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="orders",indexes={@Index(name="idx_orders_customer",columnList="customer_id"),@Index(name="idx_orders_partner",columnList="delivery_partner_id"),@Index(name="idx_orders_status",columnList="status")}) public class Order{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Version private Long version;@ManyToOne(optional=false)private UserAccount customer;@ManyToOne private UserAccount deliveryPartner;@Enumerated(EnumType.STRING)@Column(nullable=false)private OrderStatus status=OrderStatus.PENDING;@Enumerated(EnumType.STRING)private PaymentMethod paymentMethod=PaymentMethod.COD;@Enumerated(EnumType.STRING)private PaymentStatus paymentStatus=PaymentStatus.PENDING;@Column(nullable=false,precision=19,scale=2)private BigDecimal subtotal=BigDecimal.ZERO;@Column(nullable=false,precision=19,scale=2)private BigDecimal deliveryFee=BigDecimal.ZERO;@Column(nullable=false,precision=19,scale=2)private BigDecimal total=BigDecimal.ZERO;private String currencyCode="INR";@ManyToOne private Address deliveryAddress;private String cancellationReason;private Instant createdAt=Instant.now();private Instant updatedAt=Instant.now();private Instant acceptedAt,pickedUpAt,outForDeliveryAt,deliveredAt;
 @Enumerated(EnumType.STRING)@Column(name="delivery_status",nullable=false,length=30)private DeliveryStatus deliveryStatus=DeliveryStatus.ORDER_PLACED;
 private Instant assignedAt,packingAt,onTheWayAt,arrivedAt;
 @Column(name="dispatch_last_attempt_at")private Instant dispatchLastAttemptAt;
 public Long getVersion(){return version;}
 public DeliveryStatus getDeliveryStatus(){return deliveryStatus;}
 /** Moves the delivery lifecycle, stamps the step time and keeps the legacy order status in sync. */
 public void applyDeliveryStatus(DeliveryStatus next,Instant at){deliveryStatus=next;switch(next){case DELIVERY_ASSIGNED->assignedAt=at;case PACKING->packingAt=at;case ON_THE_WAY->{onTheWayAt=at;outForDeliveryAt=at;}case ARRIVED->arrivedAt=at;case DELIVERED->deliveredAt=at;default->{}}setStatus(next.legacyOrderStatus());}
 public Instant getAssignedAt(){return assignedAt;}public Instant getPackingAt(){return packingAt;}public Instant getOnTheWayAt(){return onTheWayAt;}public Instant getArrivedAt(){return arrivedAt;}
 public Instant getDispatchLastAttemptAt(){return dispatchLastAttemptAt;}public void setDispatchLastAttemptAt(Instant v){dispatchLastAttemptAt=v;}
 public Instant stepTime(DeliveryStatus s){return switch(s){case DELIVERY_ASSIGNED->assignedAt;case PACKING->packingAt;case ON_THE_WAY->onTheWayAt;case ARRIVED->arrivedAt;case DELIVERED->deliveredAt;case ORDER_PLACED->createdAt;default->null;};}
 public Long getId(){return id;}public UserAccount getCustomer(){return customer;}public void setCustomer(UserAccount v){customer=v;}public UserAccount getDeliveryPartner(){return deliveryPartner;}public void setDeliveryPartner(UserAccount v){deliveryPartner=v;}public OrderStatus getStatus(){return status;}public void setStatus(OrderStatus v){status=v;updatedAt=Instant.now();}public PaymentMethod getPaymentMethod(){return paymentMethod;}public void setPaymentMethod(PaymentMethod v){paymentMethod=v;}public PaymentStatus getPaymentStatus(){return paymentStatus;}public void setPaymentStatus(PaymentStatus v){paymentStatus=v;}public BigDecimal getSubtotal(){return subtotal;}public void setSubtotal(BigDecimal v){subtotal=v;}public BigDecimal getDeliveryFee(){return deliveryFee;}public void setDeliveryFee(BigDecimal v){deliveryFee=v;}public BigDecimal getTotal(){return total;}public void setTotal(BigDecimal v){total=v;}public String getCurrencyCode(){return currencyCode;}public Address getDeliveryAddress(){return deliveryAddress;}public void setDeliveryAddress(Address v){deliveryAddress=v;}public String getCancellationReason(){return cancellationReason;}public void setCancellationReason(String v){cancellationReason=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public Instant getAcceptedAt(){return acceptedAt;}public void setAcceptedAt(Instant v){acceptedAt=v;}public Instant getPickedUpAt(){return pickedUpAt;}public void setPickedUpAt(Instant v){pickedUpAt=v;}public Instant getOutForDeliveryAt(){return outForDeliveryAt;}public void setOutForDeliveryAt(Instant v){outForDeliveryAt=v;}public Instant getDeliveredAt(){return deliveredAt;}public void setDeliveredAt(Instant v){deliveredAt=v;}}
